sys_script_include.script:
var PEAR_Utils3 = Class.create();
PEAR_Utils3.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {


	getUserTypesOfBusinessProfile: function(bp_sysId) {

		if (!bp_sysId) {
			bp_sysId = this.getParameter('sysparm_bp_sysId');
		}
		gs.info('getUserTypesOfBusinessProfile ' + bp_sysId);

		var bp_user_type = [];
		var bpa = new GlideRecord('x_587457_pear_business_part_of_app_access');
		bpa.addQuery('business_profile_id',bp_sysId);
		bpa.query();
		while(bpa.next())
		{
			bpa_user_type = bpa.user_type_list.toString().split(',')
			for(i=0;i<bpa_user_type.length;i++)
				if(!bp_user_type.toString().contains(bpa_user_type[i].toString()))
					bp_user_type.push(bpa_user_type[i].toString())

		}

			if(bp_user_type.length ==0)
				return 'sys_id=XYZ';
			else
				return 'sys_idIN' + bp_user_type.toString();
	},

	getLicensesOfBusinessProfile: function(bp_sysId,requestedFor) {

		if (!bp_sysId) {
			bp_sysId = this.getParameter('sysparm_bp_sysId');
		}
		if (!requestedFor) {
			requestedFor = this.getParameter('sysparm_requestedFor');
		}

		var pmng_user = new GlideRecord('x_587457_pear_pmng_user');
		if(gs.nil(requestedFor))
			pmng_user.get('uid',gs.getUserID());
		else
			pmng_user.get('uid',requestedFor);

		// gs.info('getLicensesOfBusinessProfile ' + bp_sysId + ' requestedFor pmng_user ' + pmng_user.sys_id);


		var licenses = [];
		var bpa = new GlideRecord('x_587457_pear_business_part_of_app_access');
		bpa.addEncodedQuery("status=enable")
		bpa.addQuery('business_profile_id',bp_sysId);
		bpa.addEncodedQuery("user_type_listLIKE" + pmng_user.user_type);	// MS	-> maybe condition to if(!gs.nil(requestedFor))
		bpa.query();
		while(bpa.next())
			if(!licenses.toString().contains(bpa.license.toString()))
				licenses.push(bpa.license.toString())

		if(licenses.length ==0)
			return 'sys_id=XYZ';
		else
			return 'sys_idIN' + licenses.toString();
	},	

	getAccessProfilesOfBusinessProfile: function(bp_sysId,requestedFor) {

		if (!bp_sysId) {
			bp_sysId = this.getParameter('sysparm_bp_sysId');
		}
		if (!requestedFor) {
			requestedFor = this.getParameter('sysparm_requestedFor');
		}

		var pmng_user = new GlideRecord('x_587457_pear_pmng_user');
		if(gs.nil(requestedFor))
			pmng_user.get('uid',gs.getUserID());
		else
			pmng_user.get('uid',requestedFor);

		gs.info('getAccessProfilesOfBusinessProfile ' + bp_sysId + ' requestedFor pmng_user ' + pmng_user.sys_id);


		var access_profiles = [];
		var bpa = new GlideRecord('x_587457_pear_business_part_of_app_access');
		bpa.addEncodedQuery("status=enable")
		bpa.addQuery('business_profile_id',bp_sysId);
		bpa.addEncodedQuery("user_type_listLIKE" + pmng_user.user_type);	// MS	-> maybe condition to if(!gs.nil(requestedFor))
		bpa.query();
		while(bpa.next())
			if(!access_profiles.toString().contains(bpa.access_profile.toString()))
				access_profiles.push(bpa.access_profile.toString())

		if(access_profiles.length ==0)
			return 'sys_id=XYZ';
		else
			return 'sys_idIN' + access_profiles.toString();
	},

	getApplicationsOfBusinessProfile: function(bp_sysId) {

		if (!bp_sysId) {
			bp_sysId = this.getParameter('sysparm_bp_sysId');
		}
		gs.info('getApplicationsOfBusinessProfile ' + bp_sysId);

		var applications = [];
		var bpa = new GlideRecord('x_587457_pear_business_part_of_app_access');
		bpa.addEncodedQuery("status=enable")
		bpa.addQuery('business_profile_id',bp_sysId)
		bpa.query();
		while(bpa.next())
			if(!applications.toString().contains(bpa.application.toString()))
				applications.push(bpa.application.toString())

		if(applications.length ==0)
			return 'sys_id=XYZ';
		else
			return 'sys_idIN' + applications.toString();
	},


	getConcernedfBusinessPartsOfApplicativeAccess: function(aa_sysId) {

		var bp_array = [];
		var AllLabelComponents = ['technical_role','business_unit','organization','project','group','company'];
		if (!aa_sysId) {
			aa_sysId = this.getParameter('sysparm_aa_sysId');
		}

		// gs.info('getConcernedfBusinessPartsOfApplicativeAccess ' + aa_sysId);

		var aa = new GlideRecord('x_587457_pear_applicative_access');
		if(aa.get(aa_sysId) /*&& bp.status == 'enable'*/)
		{
			var bp = new GlideRecord('x_587457_pear_business_part_of_app_access');
			bp.addQuery('application',aa.application)
			bp.query();
			var concernerdBp;
			while(bp.next())
			{
				concernerdBp = true;
				if(!gs.nil(bp.technical_role) && bp.technical_role != aa.technical_role)
					concernerdBp = false;
				if(!gs.nil(bp.business_unit) && bp.business_unit != aa.business_unit)
					concernerdBp = false;
				if(!gs.nil(bp.project) && bp.project != aa.project)
					concernerdBp = false;
				// gs.info('getConcernedfBusinessPartsOfApplicativeAccess bp.label ' + bp.label + ' aa.label ' + aa.label + ' concernerdBp ' + concernerdBp);

				if(concernerdBp == true)
					bp_array.push(bp.sys_id.toString())
			}
		}
		if(bp_array.length ==0)
			return 'sys_id=XYZ';
		else
			return 'sys_idIN' + bp_array.toString();
	},

	getLicenseByBp: function(rowsJson,requestedFor) {

		if (!rowsJson) {
			rowsJson = this.getParameter('sysparm_rowsJson') || '[]';
		}
		if (!requestedFor) {
			requestedFor = this.getParameter('sysparm_requestedFor') || '[]';
		}		
		gs.info('getLicenseByBp rowsJson ' + rowsJson + ' requestedFor ' + requestedFor);

		var rows = [];
		try { rows = JSON.parse(rowsJson); } catch (e) { rows = []; }

		var outMap = {};

		for(z=0;z<rows.length;z++)
		{
			var bpIds = rows[z].business_profile.toString().split(',');
			var prjIds = rows[z].projects.toString().split(',');
			if (!bpIds.length)
				return '[]';
			if (!prjIds.length)
				return '[]';

			var l = new GlideRecord('x_587457_pear_license');
			gs.info('getLicenseByBp this.getLicensesOfBusinessProfile(bpIds,requestedFor) ' + this.getLicensesOfBusinessProfile(bpIds,requestedFor))
			l.addEncodedQuery(this.getLicensesOfBusinessProfile(bpIds,requestedFor));
			l.orderBy('label');
			l.query();
			while(l.next())
			{
				var id = l.getUniqueValue();
				outMap[id] = {
					number: l.getDisplayValue('number'),
					label: l.getDisplayValue('label'),
					application: l.getDisplayValue('application'),
					max_number: l.getDisplayValue('applicmax_numberation')
				};			
			}
		}
		var out = Object.keys(outMap).map(function(k){ return outMap[k]; });
		// gs.info('getLicenseByBp OUTPUT json ' + new global.JSON().encode(out));
		return new global.JSON().encode(out);
	},


	getAccessProfileByBp: function(rowsJson,requestedFor) {
		if (!rowsJson) {
			rowsJson = this.getParameter('sysparm_rowsJson') || '[]';
		}
		if (!requestedFor) {
			requestedFor = this.getParameter('sysparm_requestedFor') || '[]';
		}
		gs.info('getAccessProfileByBp rowsJson ' + rowsJson + ' requestedFor ' + requestedFor);

		var rows = [];
		try { rows = JSON.parse(rowsJson); } catch (e) { rows = []; }

		var outMap = {};

		for(z=0;z<rows.length;z++)
		{
			var bpIds = rows[z].business_profile.toString().split(',');
			var prjIds = rows[z].projects.toString().split(',');
			if (!bpIds.length)
				return '[]';
			if (!prjIds.length)
				return '[]';

			var ap = new GlideRecord('x_587457_pear_access_profile');
			ap.addEncodedQuery(this.getAccessProfilesOfBusinessProfile(bpIds,requestedFor));
			ap.orderBy('label')
			ap.query();
			while(ap.next())
			{
				var id = ap.getUniqueValue();
				outMap[id] = {
					number: ap.getDisplayValue('number'),
					label: ap.getDisplayValue('label'),
					code: ap.getDisplayValue('code'),
					application: ap.getDisplayValue('application'),
					};			
			}
		}
		var out = Object.keys(outMap).map(function(k){ return outMap[k]; });
		// gs.info('getAccessProfileByBp OUTPUT json ' + new global.JSON().encode(out));
		return new global.JSON().encode(out);
	},

	getApplicativeAccessByBp: function(rowsJson,requestedFor) {



		if (!rowsJson) {
			rowsJson = this.getParameter('sysparm_rowsJson') || '[]';
		}

		if (!requestedFor) {
			requestedFor = this.getParameter('sysparm_requestedFor') || '';
		}



		var pmng_user = new GlideRecord('x_587457_pear_pmng_user');
		if(gs.nil(requestedFor))
			pmng_user.get('uid',gs.getUserID());
		else
			pmng_user.get('uid',requestedFor);

		// gs.info('getApplicativeAccessByBp rowsJson ' + rowsJson + ' requestedFor pmng_user ' + pmng_user.sys_id);

		var rows = [];
		try { rows = JSON.parse(rowsJson); } catch (e) { rows = []; }

		var outMap = {};

		for(z=0;z<rows.length;z++)
		{
			var bpIds = rows[z].business_profile.toString().split(',');
			var prjIds = rows[z].projects.toString().split(',');

			if (!bpIds.length)
				return '[]';

			if (!prjIds.length)
				return '[]';

			var parts = new GlideRecord('x_587457_pear_business_part_of_app_access');
			parts.addQuery('business_profile_id', 'IN', bpIds.join(','));
			parts.addEncodedQuery("user_type_listLIKE" + pmng_user.user_type);	// MS	-> maybe condition to if(!gs.nil(requestedFor))
			parts.query();
			gs.info('getApplicativeAccessByBp parts count ' + parts.getRowCount());
			gs.info('getApplicativeAccessByBp parts query ' + parts.getEncodedQuery());
			while (parts.next()) {
				var aa = new GlideRecord('x_587457_pear_applicative_access');
				aa.addEncodedQuery(this.getConcernedApplicativeAccessOfBusinessPart(parts.sys_id,requestedFor));
				if(parts.application.applicative_access_format.format.contains("project"))
					aa.addQuery('project', 'IN', prjIds.join(','));
				aa.query();
				// gs.info('getApplicativeAccessByBp aa check project ' + parts.application.applicative_access_format.format);
				gs.info('getApplicativeAccessByBp aa count ' + aa.getRowCount());
				gs.info('getApplicativeAccessByBp aa query ' + aa.getEncodedQuery());
				while (aa.next()) {
					var id = aa.getUniqueValue();
					outMap[id] = {
						business_part: parts.getValue('label'),
						number: aa.getDisplayValue('number'),
						label: aa.getDisplayValue('label'),
						application: aa.getDisplayValue('application'),
						app_access_format: aa.application.applicative_access_format.format.toString(),
						technical_role: aa.getDisplayValue('technical_role'),
						business_unit: aa.getDisplayValue('business_unit'),
						organization: aa.getDisplayValue('organization'),
						project: aa.getDisplayValue('project'),
						group: aa.getDisplayValue('group'),
						company: aa.getDisplayValue('company')
					};
				}
			}
		}
		var out = Object.keys(outMap).map(function(k){ return outMap[k]; });
		gs.info('getApplicativeAccessByBp OUTPUT json ' + new global.JSON().encode(out));
		return new global.JSON().encode(out);
	},

	getProjectsByBusinessProfile: function (BusinessProfileId) {

		gs.info('getProjectsByBusinessProfile START for Business profile ' + BusinessProfileId)

		var BusinessProfileRequiredProjects = [];
		var BusinessPart = new GlideRecord('x_587457_pear_business_part_of_app_access');
		BusinessPart.addQuery('business_profile_id', BusinessProfileId);
		// BusinessPart.addQuery('status', 'active');
		BusinessPart.query();
		gs.info('getProjectsByBusinessProfile BusinessPart query ' + BusinessPart.getEncodedQuery());
		var ApplicativeAccessquery = "";
		while(BusinessPart.next())
		{
			if(ApplicativeAccessquery == "")
				ApplicativeAccessquery += this.getConcernedApplicativeAccessOfBusinessPart(BusinessPart.sys_id);
			else
				ApplicativeAccessquery = ApplicativeAccessquery + "^NQ" + this.getConcernedApplicativeAccessOfBusinessPart(BusinessPart.sys_id);
		}
		if(ApplicativeAccessquery == "")
			return ""
		else
		{
			var ApplicativeAccess = new GlideRecord('x_587457_pear_applicative_access');
			ApplicativeAccess.addEncodedQuery(ApplicativeAccessquery);
			ApplicativeAccess.query();
			while(ApplicativeAccess.next())
				if(!BusinessProfileRequiredProjects.toString().contains(ApplicativeAccess.project.toString()))
					BusinessProfileRequiredProjects.push(ApplicativeAccess.project.toString())
			return BusinessProfileRequiredProjects
		}
    },

	getBusinessProfilesByUser: function () {						// It is used?
		var pmng_user = new GlideRecord('x_587457_pear_pmng_user');
		pmng_user.get('uid',gs.getUserID());
		gs.info('getBusinessProfilesByUser START for user ' + gs.getUserID() + ' User Type: ' + pmng_user.user_type);
		var bp_array = [];
		var bp = new GlideRecord('x_587457_pear_business_profile');
		bp.addQuery('status','enable');
		bp.addEncodedQuery("user_typeLIKE" + pmng_user.user_type);	// MS	-> maybe condition to if(!gs.nil(requestedFor))
		bp.query();
		while(bp.next())
			bp_array.push(bp.sys_id.toString())

		return 'sys_idIN' + bp_array.toString()

	},

	getConcernedApplicativeAccessOfBusinessPart: function (bp_sysId,requestedFor) {

		if (!bp_sysId) {
			bp_sysId = this.getParameter('sysparm_bp_sysId') || '[]';
		}

		if (!requestedFor) {
			requestedFor = this.getParameter('sysparm_requestedFor') || '';
		}

		var pmng_user = new GlideRecord('x_587457_pear_pmng_user');
		if(gs.nil(requestedFor))
			pmng_user.get('uid',gs.getUserID());
		else
			pmng_user.get('uid',requestedFor);

		var query = "";
		var aa_array = [];
		var AllLabelComponents = ['technical_role','business_unit','organization','project','group','company'];
		if (!bp_sysId) {
			bp_sysId = this.getParameter('sysparm_bp_sysId');
		}

		var bp_LabelCompontents = [];
		var bp = new GlideRecord('x_587457_pear_business_part_of_app_access');
		if(bp.get(bp_sysId) && bp.status == 'enable')
		{
			for (i=0; i<AllLabelComponents.length;i++)
			{
				if(!gs.nil(bp.getValue(AllLabelComponents[i])))
					bp_LabelCompontents.push(AllLabelComponents[i])
			}

			var aa = new GlideRecord('x_587457_pear_applicative_access');
			aa.addQuery('enable',true);
			aa.addEncodedQuery("user_typeLIKE" + pmng_user.user_type);	// MS
			for(j=0;j<bp_LabelCompontents.length;j++)
			{
				aa.addQuery(bp_LabelCompontents[j],bp.getValue(bp_LabelCompontents[j]))
			}
			aa.query();
			gs.info('getConcernedApplicativeAccessOfBusinessPart ' + aa.getEncodedQuery())
			query = aa.getEncodedQuery();
			while(aa.next())
			{
				aa_array.push(aa.sys_id.toString())
			}
		}
		if(aa_array.length ==0)
			return 'sys_id=XYZ';
		else
			return 'sys_idIN' + aa_array.toString();
		//return query;
	}, 

	getApplicativeAccessFormatbyApp: function (Application){

		var result = "";
		if (!Application) {
			Application = this.getParameter('sysparm_Application');
		}
		gs.info('getApplicativeAccessFormatbyApp Application ' + Application)
		var app = new GlideRecord('x_587457_pear_application');
		if(app.get(Application))
		{
			if(gs.nil(app.applicative_access_format.separator))
				result = app.applicative_access_format.format;
			else
				result = app.applicative_access_format.format + "|" + app.applicative_access_format.separator;
		}

		return result;

	},

    type: 'PEAR_Utils3'
});
